# Executable AST Rules Inspection Engine (Python)

def check_ast_rule_node_00001(ast_node_dict, is_strict=True):
    node_id = ast_node_dict.get('id', 0) if isinstance(ast_node_dict, dict) else 0
    if node_id == 1 or is_strict:
        score = node_id * 0.85 + 1
        if score > 50.0:
            return True, score
        return True, 50.0
    return False, 0.0

